{
  "scopeId": "GUARD-POLICY-01-WHOLE-TEXT",
  "role": "architekt",
  "scopeStatus": "COMPLETE",
  "scopeStatusMeaning": "Vollstaendige eigene Textbeurteilung P1-P7; keine Behauptung fehlerfreien Verfahrens oder elterlicher Wertbarkeit.",
  "wholeTextVote": "JA",
  "unconditional": true,
  "conditions": [],
  "requiredTextChanges": [],
  "sections": [
    {
      "id": "P1",
      "status": "PASS_TEXT",
      "proposalLines": {
        "from": 2,
        "through": 4
      },
      "reason": "Prospektiver Gegenstand und bestehende Normhierarchie getrennt; historische G-Beratung ist keine Stimme; keine Entscheidung ueber Quellenwahrheit, Tests oder Rechte.",
      "sourceEvidence": [
        "ADR0003 D6",
        "ADR0004 A5",
        "proposal.md P1"
      ]
    },
    {
      "id": "P2",
      "status": "PASS_TEXT",
      "proposalLines": {
        "from": 6,
        "through": 28
      },
      "reason": "Alle fuenf typisierten Guards totalisiert: gemeinsames Veto vor Alternativen, Invalidierung vor Unsicherheit innerhalb der Kette, nichtleere passende unabhaengige Alternative; keine Vakuumwahrheit. Negative Beobachtung und fehlende Kette getrennt; Fachwert und Guard an derselben Kette. Historische Hilfe bleibt ankerbezogen, direkte Antwort ersetzt kein Material.",
      "sourceEvidence": [
        "ADR0003 D1-D5",
        "ADR0004 A1-A3",
        "CONTRACT.md section 4",
        "catalogue.json /facts/5 through /facts/21"
      ]
    },
    {
      "id": "P3",
      "status": "PASS_TEXT",
      "proposalLines": {
        "from": 30,
        "through": 40
      },
      "reason": "Gemeinsamer Kontext, gueltige Abgabe und Beobachtungsvollstaendigkeit getrennt; invalidierter notwendiger Kontext laesst keine abhaengigen Guards wahr. Fehlender Abschluss unbekannt, Invalidierung keine erfundene Nichtabgabe/Luecke. Integritaet blockiert Fachbericht; Fenster und alle unverkuerzten Regeln/Fallbacks erhalten.",
      "sourceEvidence": [
        "ADR0003 D2.7-D2.9,D4",
        "CONTRACT.md sections 4,6",
        "catalogue.json /facts/0 through /facts/2",
        "rule-records.json /0/logic/requires through /7/logic/requires"
      ]
    },
    {
      "id": "P4",
      "status": "PASS_TEXT",
      "proposalLines": {
        "from": 42,
        "through": 48
      },
      "reason": "Definitive Ergebnisbasis ist nachvollziehbare neue Produktwahl. Die abweichende historische Architekturdefinition bleibt korrekt zitiert statt widerlegt. Keine Automatik erzeugt fachlichen Fehler; notwendige Gegenprobe explizit NOT_MATERIALISED/NOT_RUN.",
      "sourceEvidence": [
        "historical architekt decision.json /guardDefinitions/0/values/wahr",
        "historical didaktik decision.json /guardDefinitions/0",
        "historical redteam decision.json /guardDefinitions/0",
        "catalogue.json /facts/3 and /facts/4"
      ]
    },
    {
      "id": "P5",
      "status": "PASS_TEXT",
      "proposalLines": {
        "from": 50,
        "through": 59
      },
      "reason": "Alle sechs Originalfaelle einschliesslich ihrer Input-/Szenen-/Oraclebindings sowie 30 Ereignis- und 42 Hilfereferenzen dokumentarisch verglichen. Prospektive Aussagen von alten Oracles getrennt. C-HELP-ANCHOR und C-U07 bleiben voneinander unabhaengig offen; kein Integritaetslauf, keine Ein-Slot-Weltaktionsgrenze und keine neue ganze Oraclematrix.",
      "sourceEvidence": [
        "input-bindings.json /selectedCases/0 through /selectedCases/5",
        "author/handoff.json /caseIllustrations/0 through /caseIllustrations/5",
        "historical didaktik decision.json /conditions/1 and /conditions/2"
      ]
    },
    {
      "id": "P6",
      "status": "PASS_TEXT",
      "proposalLines": {
        "from": 61,
        "through": 67
      },
      "reason": "RT-GT-01 bis RT-GT-05 und alle Norm-/Integrationsgrenzen erhalten. Bestehende ADR-Ableitung, neue Produktpraezisierung und technische Integration getrennt; U07-Apphilfequellenkonflikt nicht wegabgestimmt. Keine Schliessung eines Befunds oder Gates.",
      "sourceEvidence": [
        "historical redteam decision.json /findings/0 through /findings/4",
        "catalogue.json /facts/0 through /facts/2 and /facts/17 through /facts/21",
        "CONTRACT.md sections 4,6",
        "rule-records.json /0/logic/requires through /7/logic/requires",
        "open-issues.json"
      ]
    },
    {
      "id": "P7",
      "status": "PASS_TEXT",
      "proposalLines": {
        "from": 69,
        "through": 73
      },
      "reason": "Exakter Ganztexthash, drei frische vollstaendige Rollen mit hoechstens zwei gleichzeitig, separate Ratifikation und anschliessendes vollstaendiges Manifestgate. Historische Daten/FAILs/INCONCLUSIVE bleiben erhalten; keine Implementation.",
      "sourceEvidence": [
        "ADR0003 D6",
        "ADR0004 A5",
        "proposal.md P7"
      ]
    }
  ],
  "findings": [
    {
      "id": "ARCH-GP03-R01",
      "severity": "high",
      "kind": "RETAINED_SOURCE_CONFLICT_NOT_A_NEW_TEXT_DEFECT",
      "status": "RETAINED_NOT_CLOSED",
      "finding": "Die beiden D4-Originalprofile halten alle fuenf Guards wahr, obwohl ein notwendiger gemeinsamer Kontextbeleg adressiert invalidiert wird. P2/P3/P5 behandelt diesen Konflikt offen und konsistent, statt nur hinter observation.valid zu verstecken.",
      "evidence": [
        "inputs/V2-D4-invalid-open.json /events/5/payload/eventIds/0",
        "inputs/V2-D4-invalid-close.json /events/5/payload/eventIds/0",
        "expectations/V2-D4-invalid-open.json /facts",
        "expectations/V2-D4-invalid-close.json /facts",
        "proposal.md lines 13,32,56-57"
      ],
      "blocksThisTextVote": false,
      "requiredTextChange": null
    },
    {
      "id": "ARCH-GP03-R02",
      "severity": "medium",
      "kind": "RETAINED_SOURCE_CONFLICT_NOT_A_NEW_TEXT_DEFECT",
      "status": "RETAINED_NOT_CLOSED",
      "finding": "U07-App enthaelt beobachtete App-Demos, das Originaloracle aber support.general unbekannt. Der Konflikt bleibt in P6 erhalten; er entscheidet weder Zielhinweis noch ganze Hilfepolicy und kommt in keinem der acht requires-Terme vor.",
      "evidence": [
        "inputs/V2-REV-U07-one-slot-two-required-undos-app.json /events/1 through /events/3",
        "expectations/V2-REV-U07-one-slot-two-required-undos-app.json /facts/support.general",
        "catalogue.json /facts/12",
        "proposal.md line 63"
      ],
      "blocksThisTextVote": false,
      "requiredTextChange": null
    },
    {
      "id": "ARCH-GP03-PROC01",
      "severity": "medium",
      "kind": "OWN_PROCEDURE_EXCEPTION_NOT_PRODUCT_EVIDENCE",
      "status": "RETAINED",
      "finding": "0007 wurde nach erster Kontextfortsetzung vor erneuter Bootstrapladung aufgerufen. Die verpflichtende Wiederladereihenfolge wurde nicht eingehalten. Erfolgreicher Capturelauf beweist keinen vorausgegangenen Reload. Vor 0008 wurde die exakte Bruecke neu geladen.",
      "evidence": [
        "own journal 0007.operation.json,0007.request.json,0007.result.json",
        "protocol.md lines 13-35",
        "architecture-procedural-addendum.json /instruction",
        "own continuation-notes.json"
      ],
      "blocksThisTextVote": false,
      "parentEligibilityDecision": "NOT_ISSUED_BY_REVIEWER",
      "requiredTextChange": null
    }
  ],
  "remainingIntegrationObligations": [
    {
      "id": "C-HELP-ANCHOR",
      "status": "SPECIFICATION_PENDING",
      "description": "Gueltige Teilfensterbindung der sieben Coverageeintraege [0,4] auf Kindanker seq 1 separat spezifizieren; unabhaengige unqualifizierte Claims erhalten."
    },
    {
      "id": "C-U07",
      "status": "SPECIFICATION_PENDING",
      "description": "Revisionsgebundene U07-Qualifikation und Integritaetsbeurteilung separat; unbegrenzte Lueckenlesart, historische INCONCLUSIVE unveraendert."
    },
    {
      "id": "RESULT-AUTOMATIC-COUNTERPROBE",
      "status": "NOT_MATERIALISED_NOT_RUN",
      "description": "Sonst gleiche Automatik-/Bestaetigungs-/Korrekturkette samt Zwischenpraefixen vor spaeterer Umsetzung materialisieren und fremd pruefen."
    },
    {
      "id": "FULL-MANIFEST-INTEGRATION",
      "status": "OPEN",
      "description": "Alle Katalog-/Vertrags-/Regel-/Report-/Fenster-/Hilfe-/Wortlautbindungen, ADR0004, externe Pflichtinventur, Vertrauensanker, sichere Beschaffung, authentische Zusatzgatebelege und vollstaendiger Nenner mit eigenem Freeze/Fremdreview."
    }
  ],
